insert into public.posts (id, author_id, kind, title, subtitle, body, category, location, tag, photos, photo_total, more_count, sign, like_count, share_count, created_at) values
  ('00000000-0000-4000-8000-000000000001', (select id from public.profiles where handle = 'emmanuel'), 'featured', 'How to live in Nyabugogo', '(student guide)', 'Nyabugogo is busy, but it''s a great place to live if you know where to go. Here are some useful tips, cheap food spots, and essential places you''ll need.. 🧡', 'guide food price nyabugogo', 'Nyabugogo', null, array['photo-1489493585363-d69421e0edd3','photo-1546069901-ba9599a7e63c','photo-1542838132-92c53300491e']::text[], 6, 6, 'NYABUGOGO', 124, 12, now() - interval '2 hours'),
  ('00000000-0000-4000-8000-000000000002', (select id from public.profiles where handle = 'nyira'), 'compact', 'New house available near campus', null, 'Single and shared rooms, clean, secure, Wi-Fi, water and electricity included.', 'room housing campus landlord', null, 'New', array['photo-1611892440504-42a792e24d32']::text[], 0, 0, null, 18, 3, now() - interval '5 hours'),
  ('00000000-0000-4000-8000-000000000003', (select id from public.profiles where handle = 'racheal'), 'featured', 'Today''s market prices', '(Nyabugogo)', 'Tomatoes — 600 RWF/kg · Onions — 500 RWF/kg · Rice — 1,500 RWF/kg. Prices can change, so check the update date before you go. 🥬', 'price food market vegetables', 'Nyabugogo', null, array['photo-1540420773420-3366772f4999','photo-1542838132-92c53300491e','photo-1547592180-85f173990554']::text[], 5, 3, null, 46, 5, now() - interval '6 hours'),
  ('00000000-0000-4000-8000-000000000004', (select id from public.profiles where handle = 'jean'), 'compact', 'Single room for rent in Kimironko', null, 'Quiet compound, own door, Wi-Fi and water included. 45,000 RWF per month, 10 minutes from the main road.', null, null, 'New', array['photo-1522708323590-d24dbb6b0267']::text[], 0, 0, null, 34, 7, now() - interval '8 hours'),
  ('00000000-0000-4000-8000-000000000005', (select id from public.profiles where handle = 'moses'), 'featured', 'Cheap food spots near campus', '(student tips)', 'Rice, beans, chapati and tea for under 1,500 RWF. Here are my favourite spots and the best time to go so you skip the queue. 🍲', null, 'Nyabugogo', null, array['photo-1546069901-ba9599a7e63c','photo-1547592180-85f173990554','photo-1498837167922-ddd27525d352']::text[], 6, 3, null, 58, 9, now() - interval '9 hours'),
  ('00000000-0000-4000-8000-000000000006', (select id from public.profiles where handle = 'eric'), 'compact', 'Selling my study desk (used)', null, 'Good condition and affordable, 35,000 RWF. Pick-up near campus. DM if interested.', null, null, null, array['photo-1524758631624-e2822e304c36']::text[], 0, 0, null, 21, 2, now() - interval '12 hours'),
  ('00000000-0000-4000-8000-000000000007', (select id from public.profiles where handle = 'marie'), 'featured', 'Getting to campus safely', '(transport tips)', 'Leave early, agree on the price before you board, and keep your phone out of sight in the crowd. Share your own tips below! 🚌', null, 'Nyabugogo', null, array['photo-1544620347-c4fd4a3d5957','photo-1489493585363-d69421e0edd3','photo-1519003722824-194d4455a60c']::text[], 4, 1, null, 73, 11, now() - interval '1 day');
insert into public.comments (id, post_id, author_id, parent_id, body, like_count, created_at) overriding system value values
  (1, '00000000-0000-4000-8000-000000000001', (select id from public.profiles where handle = 'aline'), null, 'This helped me so much when I moved here. Checking the water supply before paying rent is gold 🙌', 42, now() - interval '55 minutes'),
  (2, '00000000-0000-4000-8000-000000000001', (select id from public.profiles where handle = 'emmanuel'), 1, 'Glad it helped, Aline! Ask the neighbours too, they always tell the truth 😄', 9, now() - interval '40 minutes'),
  (3, '00000000-0000-4000-8000-000000000001', (select id from public.profiles where handle = 'patrick'), null, 'Add that mornings are the best time to get fresh food at good prices.', 31, now() - interval '90 minutes'),
  (4, '00000000-0000-4000-8000-000000000001', (select id from public.profiles where handle = 'grace'), null, 'Is it safe to walk back from Nyabugogo after 8pm?', 18, now() - interval '120 minutes'),
  (5, '00000000-0000-4000-8000-000000000001', (select id from public.profiles where handle = 'emmanuel'), 4, 'Stay on the main road and travel in a group. It is fine until about 9pm.', 6, now() - interval '100 minutes'),
  (6, '00000000-0000-4000-8000-000000000001', (select id from public.profiles where handle = 'moses'), null, 'The cheapest chapati and tea is near the bus park, 800 RWF 👌', 11, now() - interval '150 minutes'),
  (7, '00000000-0000-4000-8000-000000000001', (select id from public.profiles where handle = 'diane'), null, 'Saving this for next semester 📌', 7, now() - interval '200 minutes'),
  (8, '00000000-0000-4000-8000-000000000001', (select id from public.profiles where handle = 'olivier'), null, 'Which area is best for a quiet room?', 4, now() - interval '260 minutes'),
  (9, '00000000-0000-4000-8000-000000000002', (select id from public.profiles where handle = 'sandrine'), null, 'Is the price negotiable for two students sharing a room?', 36, now() - interval '70 minutes'),
  (10, '00000000-0000-4000-8000-000000000002', (select id from public.profiles where handle = 'nyira'), 9, 'Yes, we can discuss it. Message me and we can arrange a visit.', 14, now() - interval '55 minutes'),
  (11, '00000000-0000-4000-8000-000000000002', (select id from public.profiles where handle = 'patrick'), null, 'Is there a deposit and how many months do we pay upfront?', 19, now() - interval '110 minutes'),
  (12, '00000000-0000-4000-8000-000000000002', (select id from public.profiles where handle = 'marie'), null, 'How far is it from campus on foot?', 9, now() - interval '180 minutes'),
  (13, '00000000-0000-4000-8000-000000000002', (select id from public.profiles where handle = 'nyira'), 12, 'About 12 minutes on foot.', 5, now() - interval '150 minutes'),
  (14, '00000000-0000-4000-8000-000000000002', (select id from public.profiles where handle = 'moses'), null, 'Interested! I just sent you a message.', 5, now() - interval '240 minutes'),
  (15, '00000000-0000-4000-8000-000000000003', (select id from public.profiles where handle = 'moses'), null, 'Thank you Racheal! Onions went up a bit yesterday, around 600 now.', 38, now() - interval '300 minutes'),
  (16, '00000000-0000-4000-8000-000000000003', (select id from public.profiles where handle = 'grace'), null, 'Which stall has the best tomatoes?', 24, now() - interval '420 minutes'),
  (17, '00000000-0000-4000-8000-000000000003', (select id from public.profiles where handle = 'racheal'), 16, 'The second row near the entrance. Go before 9am.', 11, now() - interval '380 minutes'),
  (18, '00000000-0000-4000-8000-000000000003', (select id from public.profiles where handle = 'aline'), null, 'Rice is cheaper if you buy 5kg together.', 15, now() - interval '600 minutes'),
  (19, '00000000-0000-4000-8000-000000000003', (select id from public.profiles where handle = 'olivier'), null, 'Please post these every week 🙏', 8, now() - interval '900 minutes'),
  (20, '00000000-0000-4000-8000-000000000004', (select id from public.profiles where handle = 'diane'), null, 'Does the rent include electricity?', 27, now() - interval '300 minutes'),
  (21, '00000000-0000-4000-8000-000000000004', (select id from public.profiles where handle = 'jean'), 20, 'Yes, electricity and water are both included.', 10, now() - interval '280 minutes'),
  (22, '00000000-0000-4000-8000-000000000004', (select id from public.profiles where handle = 'patrick'), null, 'Is it available from November?', 14, now() - interval '360 minutes'),
  (23, '00000000-0000-4000-8000-000000000004', (select id from public.profiles where handle = 'marie'), null, 'Great price for Kimironko 👏', 6, now() - interval '420 minutes'),
  (24, '00000000-0000-4000-8000-000000000005', (select id from public.profiles where handle = 'grace'), null, 'The rice and beans place behind the market is my favourite. Big portions!', 51, now() - interval '480 minutes'),
  (25, '00000000-0000-4000-8000-000000000005', (select id from public.profiles where handle = 'racheal'), null, 'Thanks Moses! What time does the chapati stall open?', 33, now() - interval '520 minutes'),
  (26, '00000000-0000-4000-8000-000000000005', (select id from public.profiles where handle = 'moses'), 25, 'Around 6:30am, and it sells out by 10.', 12, now() - interval '500 minutes'),
  (27, '00000000-0000-4000-8000-000000000005', (select id from public.profiles where handle = 'olivier'), null, 'Add the tea spot near the bus park, 500 RWF 😋', 19, now() - interval '600 minutes'),
  (28, '00000000-0000-4000-8000-000000000005', (select id from public.profiles where handle = 'sandrine'), null, 'Saving this thread 🙌', 9, now() - interval '700 minutes'),
  (29, '00000000-0000-4000-8000-000000000006', (select id from public.profiles where handle = 'patrick'), null, 'Can you deliver to Kimironko?', 16, now() - interval '700 minutes'),
  (30, '00000000-0000-4000-8000-000000000006', (select id from public.profiles where handle = 'eric'), 29, 'I can help with transport if it is nearby.', 4, now() - interval '650 minutes'),
  (31, '00000000-0000-4000-8000-000000000006', (select id from public.profiles where handle = 'aline'), null, 'Is the price negotiable?', 8, now() - interval '760 minutes'),
  (32, '00000000-0000-4000-8000-000000000006', (select id from public.profiles where handle = 'moses'), null, 'Sent you a DM', 3, now() - interval '900 minutes'),
  (33, '00000000-0000-4000-8000-000000000007', (select id from public.profiles where handle = 'racheal'), null, 'Always confirm the fare before you board. Saved me many times!', 47, now() - interval '1500 minutes'),
  (34, '00000000-0000-4000-8000-000000000007', (select id from public.profiles where handle = 'grace'), null, 'Keep your bag in front of you in the crowd 🎒', 29, now() - interval '1560 minutes'),
  (35, '00000000-0000-4000-8000-000000000007', (select id from public.profiles where handle = 'marie'), 34, 'Exactly! Thanks for adding that, Grace.', 12, now() - interval '1500 minutes'),
  (36, '00000000-0000-4000-8000-000000000007', (select id from public.profiles where handle = 'patrick'), null, 'Buses before 7am are the least crowded.', 17, now() - interval '1600 minutes'),
  (37, '00000000-0000-4000-8000-000000000007', (select id from public.profiles where handle = 'diane'), null, 'Very useful, thank you 💛', 6, now() - interval '1700 minutes');
