insert into public.rooms (id, landlord_id, title, type, area, km, price, beds, bath, facilities, rating, review_count, available_from, deposit, min_stay, photos, about, rank) values
  ('r1', (select id from public.profiles where handle = 'james'), 'Single Room Near Campus', 'single', 'Nyabugogo', 1.2, 45000, 1, 'Shared', array['wifi','water','electricity','kitchen']::text[], 4.8, 36, current_date + 0, '1 month', '3 months', array['photo-1522708323590-d24dbb6b0267','photo-1540518614846-7eded433c457','photo-1484154218962-a197022b5858','photo-1560185007-cde436f6a4d0','photo-1505691938895-1758d7feb511']::text[], 'A clean and comfortable single room in a shared house. The house is quiet, safe and close to the main road, so you can walk to campus in about 15 minutes. Ideal for students.', 1),
  ('r2', (select id from public.profiles where handle = 'nyira'), '3 Bedroom House Near Nyabugogo', 'house', 'Nyabugogo', 1.6, 120000, 3, 'Private', array['wifi','water','electricity','kitchen','security']::text[], 4.9, 52, current_date + 0, '2 months', '6 months', array['photo-1568605114967-8130f3a36994','photo-1600585154340-be6161a56a0c','photo-1512917774080-9991f1c4c750','photo-1556909114-f6e7ad7d3136','photo-1522771739844-6a9f6d5f14af']::text[], 'A bright three bedroom house with a fenced garden and secure parking. Perfect for a group of friends or a small family who want space and privacy close to the bus park.', 2),
  ('r3', (select id from public.profiles where handle = 'jean'), 'Shared Room for 2 Students', 'shared', 'Kimironko', 2.4, 28000, 1, 'Shared', array['wifi','water','electricity']::text[], 4.5, 21, current_date + 8, '1 month', '3 months', array['photo-1555854877-bab0e564b8d5','photo-1522708323590-d24dbb6b0267','photo-1540518614846-7eded433c457','photo-1484154218962-a197022b5858']::text[], 'Two comfortable beds in a spacious room with a study corner. Rent is per person, which keeps it very affordable. A friendly compound with other students.', 3),
  ('r4', (select id from public.profiles where handle = 'alice'), 'Modern Studio Apartment', 'apartment', 'Kacyiru', 3.1, 95000, 1, 'Private', array['wifi','water','electricity','kitchen','security','furnished']::text[], 4.7, 18, current_date + 22, '2 months', '6 months', array['photo-1502672260266-1c1ef2d93688','photo-1493809842364-78817add7ffb','photo-1560448204-e02f11c3d0e2','photo-1556909114-f6e7ad7d3136','photo-1505691938895-1758d7feb511']::text[], 'A fully furnished studio with its own kitchen and bathroom, 24 hour security and fast Wi-Fi. A quiet and modern place for someone who wants everything ready on day one.', 4),
  ('r5', (select id from public.profiles where handle = 'jean'), 'Cozy Single Room with Own Bath', 'single', 'Kimironko', 1.8, 55000, 1, 'Private', array['wifi','water','electricity']::text[], 4.6, 27, current_date + 0, '1 month', '3 months', array['photo-1540518614846-7eded433c457','photo-1522708323590-d24dbb6b0267','photo-1560185007-cde436f6a4d0','photo-1484154218962-a197022b5858']::text[], 'A warm single room with a private bathroom and plenty of natural light. The landlord lives on the same plot, so help is always close if something needs fixing.', 5),
  ('r6', (select id from public.profiles where handle = 'eric_k'), 'Family Apartment, 2 Bedrooms', 'apartment', 'Remera', 4, 160000, 2, 'Private', array['wifi','water','electricity','kitchen','security']::text[], 4.4, 14, current_date + 38, '2 months', '12 months', array['photo-1560448204-e02f11c3d0e2','photo-1502672260266-1c1ef2d93688','photo-1493809842364-78817add7ffb','photo-1556909114-f6e7ad7d3136']::text[], 'A spacious two bedroom apartment in a gated block with parking and a shared playground. Good for families, with schools and a market within walking distance.', 6),
  ('r7', (select id from public.profiles where handle = 'nyira'), 'Budget Shared Room Near Bus Park', 'shared', 'Nyabugogo', 0.6, 20000, 1, 'Shared', array['water','electricity']::text[], 4.2, 33, current_date + 0, '1 month', '1 month', array['photo-1555854877-bab0e564b8d5','photo-1505691938895-1758d7feb511','photo-1522708323590-d24dbb6b0267']::text[], 'The most affordable option on the list. A simple, clean shared room a few minutes from the bus park, ideal if you travel a lot or just need a place to sleep and study.', 7),
  ('r8', (select id from public.profiles where handle = 'james'), 'Furnished Single Room, Quiet Compound', 'single', 'Kacyiru', 2.7, 62000, 1, 'Private', array['wifi','water','electricity','security','furnished']::text[], 4.9, 41, current_date + 8, '1 month', '3 months', array['photo-1505691938895-1758d7feb511','photo-1540518614846-7eded433c457','photo-1560185007-cde436f6a4d0','photo-1522771739844-6a9f6d5f14af','photo-1484154218962-a197022b5858']::text[], 'A furnished room with a bed, desk, wardrobe and fast Wi-Fi in a calm, gated compound. Quiet at night, which makes it great for exam season.', 8),
  ('r9', (select id from public.profiles where handle = 'alice'), 'Student House, 4 Rooms to Share', 'house', 'Remera', 3.6, 38000, 4, 'Shared', array['wifi','water','electricity','kitchen']::text[], 4.3, 24, current_date + 0, '1 month', '3 months', array['photo-1512917774080-9991f1c4c750','photo-1568605114967-8130f3a36994','photo-1556909114-f6e7ad7d3136','photo-1522771739844-6a9f6d5f14af']::text[], 'A lively student house with four rooms, a shared kitchen and a living room. Rent is per room. Housemates are mostly final-year students who keep the house tidy.', 9);
